def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>These patent drawings cover the parts of a house that are hardest to get right by eye: insulation, rainwater, chimneys and heat, roof and span trusses, and light. They run from things you can make with hand tools (a hay-or-eelgrass insulation quilt, a cistern cut-off and strainer, a wire-cloth spark arrester) through timber-and-rod trusses, to a cast-iron cook stove and a tubular oil lantern. All are expired and free to copy. Use them with Parts 5&ndash;7 of this guide, and keep to the chimney clearances in section 7.2.</p>"
UNPATENTED = ["Log-cabin notching and chinking, cob, adobe, rammed earth, cordwood masonry and the pit privy are traditional methods that anyone may use."]
PATENTS = [
P("US488869","b5/cd/aa/fbb051d81d8c57/US488869.pdf","cf/23/e9/2290093387e329/US488869-drawings-page-1.png","A","1892-12-27","Samuel Cabot (Boston, Massachusetts)","Packing for builders' use",
  "Insulation for walls, floors and roofs to cut the passage of heat and sound. A layer of hay, straw or eel-grass is stitched in rows a few inches apart onto stout paper, strawboard or cloth, and the whole is fireproofed with mineral matter. You can make a quilt like this from dry grass and salvaged paper or cloth (see section 6.3).","Fig. 1 sheet in perspective; Fig. 2 edge view showing rows of stitching; Fig. 3 alternative stitching"),
P("US371697","7a/5d/02/37d7e66ae47a71/US371697.pdf","da/6a/d2/b8ce7806612d75/US371697-drawings-page-1.png","A","1887-10-18","Francis A. Miller (Home City, Ohio)","Rain-water cut-off and strainer",
  "A combined cut-off and strainer for cisterns, set in the downspout. The cut-off sends roof water either away or into the cistern, and the strainer catches debris. It was meant to be simple to build, easy to put in place and check, and self-cleaning. It is a pattern for a sheet-metal or wooden first-flush diverter (see section 5.5).","Figs. 1&ndash;7: lid, box body, cut-off valve and strainer plate"),
P("US158870","78/ed/93/9018a2099b42d3/US158870.pdf","d1/86/15/a6d6dcce030218/US158870-drawings-page-1.png","A","1875-01-19","Jacob Summers &amp; George W. Fay (Muncie, Indiana)","Improvement in spark-arresters",
  "A cone of wire cloth topped by a solid metal cap, set in a chimney flue or stovepipe. Sparks are caught and put out without blocking the smoke. You can make one from wire mesh and a tin cap to cut roof-fire risk from a wood stove.","Single sectional view of the arrester in the flue"),
P("US52375","89/d0/cd/3dcaf29684b8e7/US52375.pdf","a2/c0/54/1896cfdd5eef83/US52375-drawings-page-1.png","B","1866-01-30","Granville Moody (Piqua, Ohio)","Improvement in fire-places",
  "An iron air-heating chamber fitted inside an ordinary chimney over the hearth. A pipe brings cold outside air into it, and pipes carry the warmed air to rooms on the same floor or above. It recovers heat that would otherwise go up the chimney.","Figs. 1&ndash;2: chimney section with air chamber, inlet and warm-air pipes"),
P("US1711","63/16/e1/31513764eaa479/US1711.pdf","a8/25/eb/c68891e91e049d/US1711-drawings-page-1.png","B","1840-08-03","William Howe (Warren, Massachusetts)","Manner of constructing the truss-frames of bridges and other structures",
  "The Howe truss, meant for bridges but, in Howe's words, applicable to trussed roofs too. Wooden braces and counter-braces bear against wedge blocks, and iron rods replace the wooden posts. Screw nuts on the rods tighten the whole frame and set its camber. A strong long-span frame from timber and a few rods.","Fig. 1 truss elevation with rods, braces and bearing blocks"),
P("US3523","0c/c8/a2/309edbdfd23e78/US3523.pdf","72/45/54/80911a7541d90b/US3523-drawings-page-1.png","B","1844-04-04","Thomas W. Pratt &amp; Caleb Pratt (Norwich, Conn. and Boston, Mass.)","Truss-frame of bridges",
  "The Pratt truss: upper and lower stringers held apart by posts, with crossing diagonal iron rods. Each rod has a head at its upper end and a screw and nut at its lower end bearing on bevelled blocks, so it can be tightened. Fig. 6 shows an arched-top version.","Fig. 1 side elevation; Figs. 2&ndash;5 plans and sections; Fig. 6 arched variant"),
P("US915","7f/83/9c/35e6957adf3885/US915.pdf","b5/b5/b8/3feb3e44487899/US915-drawings-page-2.png","C","1838-09-12","Philo P. Stewart (New York, New York)","Summer and winter cooking-stove",
  "Stewart's cook stove for wood or coal. In summer the fire grate is taken out and sliding plates are put in so wood or peat can be burned, and valves and slides on the hearth and chimney control the draft and heat. A foundry is needed for the castings, but the sections show the firebox-oven-flue layout to copy in brick or sheet steel (see section 7.4).","Fig. 1 sectional side elevation; Figs. 2&ndash;3 end sections; Fig. 4 plan"),
P("US381755","eb/f5/79/6a088e01d8f7f3/US381755.pdf","ad/a2/36/120765a5de4892/US381755-drawings-page-1.png","C","1888-04-24","Lewis F. Betts, assignor in part to Robert E. Dietz (New York)","Tubular lantern",
  "A tubular oil lantern. Side tubes run from an air chamber at the top down to the oil fount. This patent improves the air chamber and the way the tubes join the fount, using ribs formed on the fount top. It is a reference for repairing salvaged lanterns, not for making one from scratch (see section 7.5).","Fig. 1 lantern elevation; Figs. 2&ndash;5 air-chamber and fount details"),
P("US291114","95/b5/65/ac583ac7584cc5/US291114.pdf","58/93/5b/2d84633e5e7b1b/US291114-drawings-page-1.png","A","1884-01-01","Joseph Wadleigh","Building-block",
  "Pressed straw-and-clay building blocks for cheap one-story houses in prairie country where timber is scarce. Straw is mixed with clay, sand, lime or cement and pressed flat in a box press so the block takes in less water than sun-dried adobe, then each block is bound with wire so it cannot spring apart before it is laid. The patent shows the mixing apparatus and press (see 4.6 Straw bale and 4.7 Earthen walls).","Fig. 1 section of the mixer and press; Fig. 3 a finished wire-bound block"),
P("US18512","17/50/e3/f2ea99a6d1933a/US18512.pdf","be/c9/44/3122e48be9bf60/US18512-drawings-page-1.png","B","1857-10-27","Simeon Marshall","Shingle-machine",
  "A machine for splitting and dressing shingles, staves and barrel headings from blocks of wood. A driven shaft works a splitting knife and dressing knives in a rigid metal frame, and the parts adjust for different thicknesses and shapes. Read with 5.4 Roofing materials.","Fig. 1 side view; Fig. 2 top view; Fig. 3 section through the knives"),
P("US822678","9c/09/15/5c3ce855525db9/US822678.pdf","15/0e/f7/7d11c6f661d429/US822678-drawings-page-1.png","C","1906-06-05","John H. Lubbers","Method of drawing glass cylinders",
  "Machine-drawn window glass. A long glass cylinder is drawn straight up out of a bath of molten glass, starting slowly and speeding up gradually, then sped up again to thin the glass where it is to be cut off. The cylinder is cut into lengths to be flattened into window glass; one drawn cylinder is as long as at least two or three hand-blown ones. This is glass-works scale; salvage glass instead (see 6.2).","The single figure: section through the drawing apparatus and glass bath"),
]
